from unittest.mock import patch

from fastapi import FastAPI
from fastapi.testclient import TestClient


def _build_app(flag_callable):
    app = FastAPI()

    @app.get("/public")
    def public():
        return {"ok": True}

    @app.get("/feature-flag", include_in_schema_if=flag_callable)
    def feature_flag():
        return {"flag": True}

    return app


def test_include_in_schema_if_excludes_when_callable_returns_false():
    flag = {"on": False}
    app = _build_app(lambda: flag["on"])
    client = TestClient(app)

    schema = client.get("/openapi.json").json()

    assert "/public" in schema["paths"]
    assert "/feature-flag" not in schema["paths"]


def test_include_in_schema_if_includes_when_callable_returns_true():
    flag = {"on": True}
    app = _build_app(lambda: flag["on"])
    client = TestClient(app)

    schema = client.get("/openapi.json").json()

    assert "/public" in schema["paths"]
    assert "/feature-flag" in schema["paths"]


def test_include_in_schema_if_can_be_toggled_at_runtime():
    flag = {"on": False}
    flag_callable = lambda: flag["on"]
    app = _build_app(flag_callable)
    client = TestClient(app)

    # Initial state: callable returns False, so /feature-flag is hidden.
    schema = client.get("/openapi.json").json()
    assert "/public" in schema["paths"]
    assert "/feature-flag" not in schema["paths"]

    # Flip the flag and clear the schema cache so the next request
    # re-evaluates include_in_schema_if from scratch.
    flag["on"] = True
    app.openapi_schema = None

    schema = client.get("/openapi.json").json()
    assert "/public" in schema["paths"]
    assert "/feature-flag" in schema["paths"]


def test_include_in_schema_if_patched_to_return_true():
    """Use unittest.mock.patch to swap the callable's return value."""
    sentinel = {"value": False}
    app = _build_app(lambda: sentinel["value"])
    client = TestClient(app)

    # Sanity check: callable currently returns False.
    initial = client.get("/openapi.json").json()
    assert "/public" in initial["paths"]
    assert "/feature-flag" not in initial["paths"]

    # Patch the dict entry the closure reads and clear the cache.
    with patch.dict(sentinel, {"value": True}):
        app.openapi_schema = None
        schema = client.get("/openapi.json").json()

    assert "/public" in schema["paths"]
    assert "/feature-flag" in schema["paths"]


def test_default_behavior_when_include_in_schema_if_is_none():
    """If the callable is None, behavior matches the boolean ``include_in_schema``."""

    app = FastAPI()

    @app.get("/always")
    def always():
        return {"ok": True}

    @app.get("/hidden", include_in_schema=False)
    def hidden():
        return {"hidden": True}

    client = TestClient(app)
    schema = client.get("/openapi.json").json()

    assert "/always" in schema["paths"]
    assert "/hidden" not in schema["paths"]
